//------------------------------------------------------------------------------
// tb_top.sv -- UVM side of the testbench (Lab 11C)
//------------------------------------------------------------------------------
`timescale 1ns/1ns

module tb_top;

  import uvm_pkg::*;
  import rand_util_pkg::*;   // rnd:: random values (common/rand_util_pkg.sv)
  `include "uvm_macros.svh"
  `include "uvm_version_compat.svh"
  import yapp_pkg::*;
