  `include "router_test_lib.sv"

  initial begin
    yapp_vif_config::set(null,            "*.tb.yapp.*",    "vif", hw_top.in0);
    hbus_vif_config::set(null,            "*.tb.hbus.*",    "vif", hw_top.hbus0);
    channel_vif_config::set(null,         "*.tb.chan0.*",   "vif", hw_top.ch0);
    channel_vif_config::set(null,         "*.tb.chan1.*",   "vif", hw_top.ch1);
    channel_vif_config::set(null,         "*.tb.chan2.*",   "vif", hw_top.ch2);
    clock_and_reset_vif_config::set(null, "*.tb.clk_rst.*", "vif", hw_top.clk_rst_if);
    run_test();
  end

endmodule : tb_top

//------------------------------------------------------------------------------
// back_to_back_test.sv -- back_to_back_test (test plan: ROUTE-04)
//------------------------------------------------------------------------------

//------------------------------------------------------------------------------
// back_to_back_test: packets with no idle cycle between them (the header in the
// cycle right after the parity byte) and with gaps of 1, 2 and 3 cycles.
//   1. router enabled (reset value of en_reg); yapp_gap_seq: 24 packets,
//      gaps 0, 1, 2, 3 in turn, to random legal addresses
//   2. the YAPP monitor measured the same gaps the sequence asked for
//      (num_gap == planned_gap), and yapp_gap_cg is at 100 %
//   3. the scoreboard matched every packet, nothing unexpected
//------------------------------------------------------------------------------
class back_to_back_test extends reg_function_test;

  yapp_gap_seq m_gap_seq;

  `uvm_component_utils(back_to_back_test)

  extern function new(string name, uvm_component parent);
  extern virtual task access_checks();

endclass : back_to_back_test

//------------------------------------------------------------------------------
// back_to_back_test -- method implementations
//------------------------------------------------------------------------------

function back_to_back_test::new(string name, uvm_component parent);
  super.new(name, parent);
endfunction : new

//------------------------------------------------------------------------------
task back_to_back_test::access_checks();
  int gaps_before[4];
  int measured;
  m_gap_seq = yapp_gap_seq::type_id::create("gap_seq");
  if (!m_gap_seq.randomize() with { m_count == 24; }) begin
    `uvm_error("GAP", "gap_seq.randomize() failed")
  end
  gaps_before = m_tb.m_yapp.m_agent.m_monitor.m_num_gap;
  stage("1. yapp_gap_seq: 24 packets with gaps of 0, 1, 2 and more cycles between them");
  m_gap_seq.start(m_yapp_seqr);

  // let the channels deliver the last packets
  repeat (400) begin
    if (m_tb.m_router_module.m_scoreboard.m_packets_matched + m_tb.m_router_module.m_scoreboard.m_packets_mismatched >= 24) begin
      break;
    end
    @(posedge m_tb.m_yapp.m_agent.m_monitor.m_vif.clock);
  end

  stage("2. the gap classes the monitor measured match the plan of the sequence, gap coverage 100%");
  foreach (gaps_before[i]) begin
    // the monitor skips the first packet after reset, the sequence its first packet
    measured = m_tb.m_yapp.m_agent.m_monitor.m_num_gap[i] - gaps_before[i];
    if (measured != m_gap_seq.m_planned_gap[i]) begin
      `uvm_error("GAP", $sformatf("gap class %0d: the monitor measured %0d packets, the sequence asked for %0d",
                                  i, measured, m_gap_seq.m_planned_gap[i]))
    end else begin
      `uvm_info("GAP", $sformatf("gap class %0d: %0d packets, as planned", i, measured), UVM_NONE)
    end
  end
  if (m_tb.m_yapp.m_agent.m_gap_cov.yapp_gap_cg.get_inst_coverage() < 100.0) begin
    `uvm_error("GAP", $sformatf("gap coverage %.1f%%, expected 100%%", m_tb.m_yapp.m_agent.m_gap_cov.yapp_gap_cg.get_inst_coverage()))
  end
  if (m_tb.m_router_module.m_scoreboard.m_packets_matched != 24 || m_tb.m_router_module.m_scoreboard.m_packets_unexpected != 0) begin
    `uvm_error("GAP", $sformatf("scoreboard: %0d matched (expected 24), %0d unexpected",
                                m_tb.m_router_module.m_scoreboard.m_packets_matched, m_tb.m_router_module.m_scoreboard.m_packets_unexpected))
  end
endtask : access_checks

//------------------------------------------------------------------------------
// backpressure_test.sv -- backpressure_test (test plan: IN-03, OUT-03, OUT-04)
//------------------------------------------------------------------------------

//------------------------------------------------------------------------------
// backpressure_test: the YAPP handshake under back-pressure.
// The channels run channel_rx_slow_seq (response delay 20..40 cycles), so a
// long packet fills the 16-byte channel FIFO before the receiver starts to
// read and the router must stall the input with in_suspend. Six packets of
// 40..63 bytes are sent; in_suspend must rise at least once, every byte must
// still reach its channel exactly once (scoreboard: 6 matched, 0 mismatched,
// 0 unexpected) and the receivers must see no bad parity.
//------------------------------------------------------------------------------
class backpressure_test extends reg_function_test;

  yapp_pkt_seq m_pkt_seq;
  int          m_num_suspend;                 // rising edges of in_suspend

  `uvm_component_utils(backpressure_test)

  extern function new(string name, uvm_component parent);
  extern function void configure_sequences();
  extern virtual task access_checks();

  // Count the rising edges of in_suspend on the YAPP interface
  extern task count_suspends();

  // Wait (bounded) until the scoreboard has judged `expected` packets
  extern task wait_scoreboard(int expected);

endclass : backpressure_test

//------------------------------------------------------------------------------
// backpressure_test -- method implementations
//------------------------------------------------------------------------------

function backpressure_test::new(string name, uvm_component parent);
  super.new(name, parent);
endfunction : new

//------------------------------------------------------------------------------
function void backpressure_test::configure_sequences();
  uvm_config_wrapper::set(this, "tb.clk_rst.agent.sequencer.run_phase",
                          "default_sequence", clk10_rst5_seq::get_type());
  uvm_config_wrapper::set(this, "tb.chan*.rx_agent.sequencer.run_phase",
                          "default_sequence", channel_rx_slow_seq::get_type());
endfunction : configure_sequences

//------------------------------------------------------------------------------
task backpressure_test::access_checks();
  int matched_before;
  int judged_before;
  matched_before = m_tb.m_router_module.m_scoreboard.m_packets_matched;
  judged_before  = m_tb.m_router_module.m_scoreboard.m_packets_matched + m_tb.m_router_module.m_scoreboard.m_packets_mismatched;
  fork
    count_suspends();
  join_none

  stage("1. slow receivers (channel_rx_slow_seq): 6 packets of 40..63 bytes fill the 16-byte FIFOs");
  m_pkt_seq = yapp_pkt_seq::type_id::create("pkt_seq");
  repeat (6) begin
    if (!m_pkt_seq.randomize() with { m_pkt_len inside {[40:63]}; }) begin
      `uvm_error("BACKPRESSURE", "pkt_seq.randomize() failed")
    end
    m_pkt_seq.start(m_yapp_seqr);
  end
  wait_scoreboard(judged_before + 6);

  stage("2. checks: in_suspend rose, 6 packets matched, nothing unexpected, no bad parity");
  if (m_num_suspend == 0) begin
    `uvm_error("BACKPRESSURE", "in_suspend never rose: the FIFO was never full, nothing was tested")
  end else begin
    `uvm_info("BACKPRESSURE", $sformatf("in_suspend rose %0d times", m_num_suspend), UVM_NONE)
  end
  if (m_tb.m_router_module.m_scoreboard.m_packets_matched != matched_before + 6) begin
    `uvm_error("BACKPRESSURE", $sformatf("scoreboard matched %0d of 6 packets",
                                         m_tb.m_router_module.m_scoreboard.m_packets_matched - matched_before))
  end
  if (m_tb.m_router_module.m_scoreboard.m_packets_unexpected != 0) begin
    `uvm_error("BACKPRESSURE", "a channel delivered a packet nobody sent (a byte was lost or duplicated)")
  end
  if (m_tb.m_yapp.m_agent.m_monitor.m_num_bad_parity != 0) begin
    `uvm_error("BACKPRESSURE", "the YAPP monitor saw bad parity: a held byte was not held")
  end
endtask : access_checks

//------------------------------------------------------------------------------
task backpressure_test::count_suspends();
  virtual interface yapp_if m_vif;
  m_vif = m_tb.m_yapp.m_agent.m_monitor.m_vif;
  forever begin
    @(posedge m_vif.in_suspend);
    m_num_suspend++;
  end
endtask : count_suspends

//------------------------------------------------------------------------------
task backpressure_test::wait_scoreboard(int expected);
  // 65 bytes plus a 40-cycle response delay per packet, with a margin
  repeat (1000) begin
    if (m_tb.m_router_module.m_scoreboard.m_packets_matched + m_tb.m_router_module.m_scoreboard.m_packets_mismatched >= expected) begin
      return;
    end
    @(posedge m_tb.m_yapp.m_agent.m_monitor.m_vif.clock);
  end
endtask : wait_scoreboard

