//------------------------------------------------------------------------------
// hbus_sweep_test.sv -- hbus_sweep_test (test plan: COV-04..07, and the HBUS
// items it checks again: REG-05/06, MEM-01/02, CNT-06)
//------------------------------------------------------------------------------

//------------------------------------------------------------------------------
// hbus_sweep_test: every address of the router read and written over the
// HBUS, every bit of ctrl_reg / en_reg written 0 and 1, data patterns in
// yapp_mem, every counter read at 0, in between and at 255
// (router_hbus_sweep_mcseq). Every read is checked by router_reference
// (check_reads = 1), so a write to a read-only or unmapped address that
// changed something fails the test. At the end the four HBUS coverage
// collectors must be at 100 %.
// About 6000 HBUS accesses and 1000 packets: the log keeps one line per access
// (HBUS monitor) and per packet (YAPP monitor); the sequencers and drivers,
// which would repeat them, are quiet (UVM_NONE).
//------------------------------------------------------------------------------
class hbus_sweep_test extends base_test;

  router_hbus_sweep_mcseq m_sweep;

  `uvm_component_utils(hbus_sweep_test)

  extern function new(string name, uvm_component parent);
  extern function void build_phase(uvm_phase phase);
  extern function void configure_sequences();
  extern function void end_of_elaboration_phase(uvm_phase phase);
  extern task run_phase(uvm_phase phase);

  // A coverage collector's percentage must be 100
  extern function void check_full(string what, real pct);

endclass : hbus_sweep_test

//------------------------------------------------------------------------------
// hbus_sweep_test -- method implementations
//------------------------------------------------------------------------------

function hbus_sweep_test::new(string name, uvm_component parent);
  super.new(name, parent);
endfunction : new

//------------------------------------------------------------------------------
function void hbus_sweep_test::build_phase(uvm_phase phase);
  uvm_config_db #(bit)::set(this, "tb.router_module.reference", "check_reads", 1'b1);
  super.build_phase(phase);
endfunction : build_phase

//------------------------------------------------------------------------------
function void hbus_sweep_test::configure_sequences();
  set_clock_and_channel_sequences();
endfunction : configure_sequences

//------------------------------------------------------------------------------
function void hbus_sweep_test::end_of_elaboration_phase(uvm_phase phase);
  super.end_of_elaboration_phase(phase);
  m_tb.m_hbus.m_masters[0].m_sequencer.set_report_verbosity_level(UVM_NONE);
  m_tb.m_hbus.m_masters[0].m_driver.set_report_verbosity_level(UVM_NONE);
  m_tb.m_yapp.m_agent.m_sequencer.set_report_verbosity_level(UVM_NONE);
  m_tb.m_yapp.m_agent.m_driver.set_report_verbosity_level(UVM_NONE);
endfunction : end_of_elaboration_phase

//------------------------------------------------------------------------------
task hbus_sweep_test::run_phase(uvm_phase phase);
  super.run_phase(phase);
  phase.raise_objection(this);
  m_sweep = router_hbus_sweep_mcseq::type_id::create("sweep");
  m_sweep.start(m_tb.m_mcseqr);
  repeat (50) begin
    @(posedge m_tb.m_yapp.m_agent.m_monitor.m_vif.clock);   // the first packet leaves its channel
  end
  stage("9. the four HBUS coverage collectors are at 100 % and every read matched the model");
  check_full("HBUS address map", m_tb.m_router_module.m_hbus_addr_cov.hbus_addr_cg.get_inst_coverage());
  check_full("ctrl_reg / en_reg bits", m_tb.m_router_module.m_hbus_bits_cov.hbus_bits_cg.get_inst_coverage());
  check_full("yapp_mem data patterns", m_tb.m_router_module.m_hbus_data_cov.hbus_data_cg.get_inst_coverage());
  check_full("counter values", m_tb.m_router_module.m_hbus_counter_cov.hbus_counter_cg.get_inst_coverage());
  stage($sformatf("done: %0d HBUS reads checked against the model, %0d mismatches, %0d memory bytes never written",
                  m_tb.m_router_module.m_reference.m_reads_checked, m_tb.m_router_module.m_reference.m_read_mismatches,
                  m_tb.m_router_module.m_reference.m_reads_unknown));
  phase.drop_objection(this);
endtask : run_phase

//------------------------------------------------------------------------------
function void hbus_sweep_test::check_full(string what, real pct);
  if (pct < 100.0) begin
    `uvm_error("HBUS_COV", $sformatf("%s coverage %.1f%%, expected 100%%", what, pct))
  end else begin
    `uvm_info("HBUS_COV", $sformatf("%s coverage 100%%", what), UVM_NONE)
  end
endfunction : check_full

//------------------------------------------------------------------------------
// parity_error_test.sv -- parity_error_test (test plan: PKT-05, IN-04, CNT-01)
//------------------------------------------------------------------------------

//------------------------------------------------------------------------------
// parity_error_test: what a wrong parity byte does.
//   1. en_reg = 0x03 (router + parity counter); 8 packets with bad parity
//      -> parity_err_cnt_reg == 8, one error pulse per packet, 1..10 cycles
//         after the parity byte (error_pulse_checker), and the packets are
//         still delivered (the router forwards them; scoreboard 8 matched)
//   2. en_reg = 0x01 (counter off); 4 more bad packets
//      -> the counter stays at 8, the pulses still come
//------------------------------------------------------------------------------
class parity_error_test extends reg_function_test;

  yapp_pkt_seq        m_pkt_seq;
  error_pulse_checker m_err_chk;

  `uvm_component_utils(parity_error_test)

  extern function new(string name, uvm_component parent);
  extern function void build_phase(uvm_phase phase);
  extern function void connect_phase(uvm_phase phase);
  extern virtual task access_checks();

  // Send `n` packets with bad parity, then wait until the channels delivered them
  extern task send_bad(int n);

endclass : parity_error_test

//------------------------------------------------------------------------------
// parity_error_test -- method implementations
//------------------------------------------------------------------------------

function parity_error_test::new(string name, uvm_component parent);
  super.new(name, parent);
endfunction : new

//------------------------------------------------------------------------------
function void parity_error_test::build_phase(uvm_phase phase);
  super.build_phase(phase);
  m_err_chk = error_pulse_checker::type_id::create("err_chk", this);
endfunction : build_phase

//------------------------------------------------------------------------------
function void parity_error_test::connect_phase(uvm_phase phase);
  super.connect_phase(phase);
  m_tb.m_yapp.m_agent.m_monitor.m_item_collected_port.connect(m_err_chk.analysis_export);
  m_err_chk.m_reference = m_tb.m_router_module.m_reference;   // router_en mirror
endfunction : connect_phase

//------------------------------------------------------------------------------
task parity_error_test::access_checks();
  uvm_status_e status;
  int matched_before;
  matched_before = m_tb.m_router_module.m_scoreboard.m_packets_matched;

  // 1. counter enabled
  stage("1. en_reg=0x03 (parity counter on): 8 bad-parity packets, 8 pulses, counter 8, all delivered");
  m_regs.en_reg.write(status, 8'h03);
  send_bad(8);
  check_counter(m_regs.parity_err_cnt_reg, 8);
  if (m_err_chk.m_num_pulses != 8) begin
    `uvm_error("PARITY", $sformatf("%0d error pulses for 8 bad packets", m_err_chk.m_num_pulses))
  end
  if (m_tb.m_router_module.m_scoreboard.m_packets_matched != matched_before + 8) begin
    `uvm_error("PARITY", "a packet with bad parity was not delivered unchanged")
  end

  // 2. counter disabled: the pulse still comes, the count does not move
  stage("2. en_reg=0x01 (counter off): 4 more bad packets, pulses still come, counter stays 8");
  m_regs.en_reg.write(status, 8'h01);
  send_bad(4);
  check_counter(m_regs.parity_err_cnt_reg, 8);
  if (m_err_chk.m_num_pulses != 12) begin
    `uvm_error("PARITY", $sformatf("%0d error pulses for 12 bad packets", m_err_chk.m_num_pulses))
  end
  if (m_err_chk.m_num_late != 0) begin
    `uvm_error("PARITY", $sformatf("%0d pulse(s) outside the 1..10 cycle window", m_err_chk.m_num_late))
  end
endtask : access_checks

//------------------------------------------------------------------------------
task parity_error_test::send_bad(int n);
  int judged_before;
  judged_before = m_tb.m_router_module.m_scoreboard.m_packets_matched + m_tb.m_router_module.m_scoreboard.m_packets_mismatched;
  m_pkt_seq = yapp_pkt_seq::type_id::create("pkt_seq");
  repeat (n) begin
    if (!m_pkt_seq.randomize() with { m_pkt_parity == PARITY_TYPE_BAD; }) begin
      `uvm_error("PARITY", "pkt_seq.randomize() failed")
    end
    m_pkt_seq.start(m_yapp_seqr);
  end
  // let the channels deliver the packets (and the last pulse come) before checking
  repeat (400) begin
    if (m_tb.m_router_module.m_scoreboard.m_packets_matched + m_tb.m_router_module.m_scoreboard.m_packets_mismatched >= judged_before + n) begin
      break;
    end
    @(posedge m_tb.m_yapp.m_agent.m_monitor.m_vif.clock);
  end
  repeat (12) begin
    @(posedge m_tb.m_yapp.m_agent.m_monitor.m_vif.clock);
  end
endtask : send_bad

