//------------------------------------------------------------------------------
// reg_access_test.sv -- reg_access_test (test library (Lab 11C: user-defined register stimulus))
// Split out of router_test_lib.sv: one class per file.
//------------------------------------------------------------------------------

//------------------------------------------------------------------------------
// reg_access_test (Lab 11C): front-door / backdoor access checks on one RW
// register (ctrl_reg) and one RO register (addr0_cnt_reg).
//
// Writing an RO register through the front door produces a real HBUS write
// cycle, which the DUT ignores; the model's mirror is not updated either
// because the field policy is RO.
//------------------------------------------------------------------------------
class reg_access_test extends base_test;

  // Convenience handle to the register block (path from the topology report)
  yapp_regs_c m_regs;

  `uvm_component_utils(reg_access_test)

  extern function new(string name, uvm_component parent);
  extern function void configure_sequences();

  extern function void connect_phase(uvm_phase phase);
  extern task run_phase(uvm_phase phase);

  // The stimulus of this test; derived tests replace it
  extern virtual task access_checks();

  // RW: front-door write -> peek, poke -> front-door read
  extern task check_rw_register(uvm_reg rg, uvm_reg_data_t wr_val, uvm_reg_data_t poke_val);

  // RO: poke -> front-door read, front-door write (ignored) -> peek unchanged
  extern task check_ro_register(uvm_reg rg, uvm_reg_data_t poke_val, uvm_reg_data_t wr_val);

endclass : reg_access_test

//------------------------------------------------------------------------------
// reg_access_test -- method implementations
//------------------------------------------------------------------------------

function reg_access_test::new(string name, uvm_component parent);
  super.new(name, parent);
endfunction : new

//------------------------------------------------------------------------------
function void reg_access_test::configure_sequences();
  set_clock_and_channel_sequences();
endfunction : configure_sequences

//------------------------------------------------------------------------------
function void reg_access_test::connect_phase(uvm_phase phase);
  m_regs = m_tb.m_yapp_rm.router_yapp_regs;
endfunction : connect_phase

//------------------------------------------------------------------------------
task reg_access_test::run_phase(uvm_phase phase);
  super.run_phase(phase);                   // drain time
  phase.raise_objection(this);
  access_checks();
  phase.drop_objection(this);
endtask : run_phase

//------------------------------------------------------------------------------
task reg_access_test::access_checks();
  check_rw_register(m_regs.ctrl_reg,      8'h25, 8'h1a);
  check_ro_register(m_regs.addr0_cnt_reg, 8'h5a, 8'h33);
endtask : access_checks

//------------------------------------------------------------------------------
task reg_access_test::check_rw_register(uvm_reg rg, uvm_reg_data_t wr_val, uvm_reg_data_t poke_val);
  uvm_status_e   status;
  uvm_reg_data_t val;
  stage($sformatf("RW register %s: front-door write 0x%02h, peek, poke 0x%02h, front-door read",
                  rg.get_name(), wr_val, poke_val));

  rg.write(status, wr_val);
  `uvm_info("REG_ACCESS", $sformatf("front-door write 0x%02h", wr_val), UVM_NONE)
  rg.peek(status, val);
  `uvm_info("REG_ACCESS", $sformatf("peek            0x%02h", val), UVM_NONE)
  if (val != wr_val) begin
    `uvm_error("REG_ACCESS", $sformatf("%s: peek returned 0x%02h, expected 0x%02h", rg.get_name(), val, wr_val))
  end

  rg.poke(status, poke_val);
  `uvm_info("REG_ACCESS", $sformatf("poke            0x%02h", poke_val), UVM_NONE)
  rg.read(status, val);
  `uvm_info("REG_ACCESS", $sformatf("front-door read 0x%02h", val), UVM_NONE)
  if (val != poke_val) begin
    `uvm_error("REG_ACCESS", $sformatf("%s: read returned 0x%02h, expected 0x%02h", rg.get_name(), val, poke_val))
  end
endtask : check_rw_register

//------------------------------------------------------------------------------
task reg_access_test::check_ro_register(uvm_reg rg, uvm_reg_data_t poke_val, uvm_reg_data_t wr_val);
  uvm_status_e   status;
  uvm_reg_data_t val;
  stage($sformatf("RO register %s: poke 0x%02h, front-door read, write 0x%02h must be ignored",
                  rg.get_name(), poke_val, wr_val));

  rg.poke(status, poke_val);
  `uvm_info("REG_ACCESS", $sformatf("poke            0x%02h", poke_val), UVM_NONE)
  rg.read(status, val);
  `uvm_info("REG_ACCESS", $sformatf("front-door read 0x%02h", val), UVM_NONE)
  if (val != poke_val) begin
    `uvm_error("REG_ACCESS", $sformatf("%s: read returned 0x%02h, expected 0x%02h", rg.get_name(), val, poke_val))
  end

  rg.write(status, wr_val);
  `uvm_info("REG_ACCESS", $sformatf("front-door write 0x%02h (RO: must be ignored)", wr_val), UVM_NONE)
  rg.peek(status, val);
  `uvm_info("REG_ACCESS", $sformatf("peek            0x%02h", val), UVM_NONE)
  if (val != poke_val) begin
    `uvm_error("REG_ACCESS", $sformatf("%s: RO register changed to 0x%02h after a write", rg.get_name(), val))
  end
endtask : check_ro_register

//------------------------------------------------------------------------------
// reg_bit_walk_test.sv -- reg_bit_walk_test (test plan: REG-02, REG-03, REG-04)
//------------------------------------------------------------------------------

//------------------------------------------------------------------------------
// reg_bit_walk_test: every bit of every register does what its policy says.
//   * RW registers (from the model, by introspection): walking one, walking
//     zero, 0x00, 0xff, 0xaa, 0x55 -- front-door write, front-door read and
//     backdoor peek must all agree, bit by bit
//   * RO registers: poke, read back, write (ignored), peek unchanged -- for
//     the values 0x00 and 0xff
// Reserved bits (ctrl_reg[7:6], en_reg[3]) are declared RW in the router and
// are therefore expected to hold what was written.
//------------------------------------------------------------------------------
class reg_bit_walk_test extends reg_access_test;

  `uvm_component_utils(reg_bit_walk_test)

  extern function new(string name, uvm_component parent);
  extern virtual task access_checks();

  // Write `pattern` through the front door; read and peek must return it
  extern task check_pattern(uvm_reg rg, uvm_reg_data_t pattern);

endclass : reg_bit_walk_test

//------------------------------------------------------------------------------
// reg_bit_walk_test -- method implementations
//------------------------------------------------------------------------------

function reg_bit_walk_test::new(string name, uvm_component parent);
  super.new(name, parent);
endfunction : new

//------------------------------------------------------------------------------
task reg_bit_walk_test::access_checks();
  uvm_status_e status;
  bit[7:0]    pattern;
  uvm_reg      all_q[$];
  uvm_reg      rw_q[$];
  uvm_reg      ro_q[$];
  m_tb.m_yapp_rm.get_registers(all_q);
  rw_q = all_q.find(r) with (r.get_rights() == "RW");
  ro_q = all_q.find(r) with (r.get_rights() == "RO");

  foreach (rw_q[i]) begin
    stage($sformatf("RW register %s: walking ones, walking zeros, 0x00 0xff 0xaa 0x55", rw_q[i].get_name()));
    for (int b = 0; b < 8; b++) begin
      pattern = 8'h01 << b;
      check_pattern(rw_q[i], pattern);
    end
    for (int b = 0; b < 8; b++) begin
      pattern = ~(8'h01 << b);
      check_pattern(rw_q[i], pattern);
    end
    check_pattern(rw_q[i], 8'h00);
    check_pattern(rw_q[i], 8'hff);
    check_pattern(rw_q[i], 8'haa);
    check_pattern(rw_q[i], 8'h55);
  end
  foreach (ro_q[i]) begin
    check_ro_register(ro_q[i], 8'h00, 8'hff);
    check_ro_register(ro_q[i], 8'hff, 8'h00);
  end

  // leave the router as reset left it
  stage("ctrl_reg and en_reg back to their reset values");
  m_regs.ctrl_reg.write(status, 8'h3f);
  m_regs.en_reg.write(status, 8'h01);
endtask : access_checks

//------------------------------------------------------------------------------
task reg_bit_walk_test::check_pattern(uvm_reg rg, uvm_reg_data_t pattern);
  uvm_status_e   status;
  uvm_reg_data_t rd_val;
  uvm_reg_data_t peek_val;
  rg.write(status, pattern);
  rg.read(status, rd_val);
  rg.peek(status, peek_val);
  if (rd_val != pattern || peek_val != pattern) begin
    `uvm_error("REG_WALK", $sformatf("%s: wrote 0x%02h, read 0x%02h, peek 0x%02h",
                                     rg.get_name(), pattern, rd_val, peek_val))
  end else begin
    `uvm_info("REG_WALK", $sformatf("%s: 0x%02h written, read and peeked", rg.get_name(), pattern), UVM_HIGH)
  end
endtask : check_pattern

