//------------------------------------------------------------------------------
// router_disable_test.sv -- router_disable_test (test plan: DROP-02, CNT-02)
//------------------------------------------------------------------------------

//------------------------------------------------------------------------------
// router_disable_test: router_en = 0 makes the router deaf.
//   1. en_reg = 0xfe (router off, every counter on); yapp_012_seq
//      -> no packet reaches a channel, the reference model reports 3 packets
//         dropped (router disabled), no counter moves, mem_size_reg stays 0
//   2. en_reg = 0xff; yapp_012_seq
//      -> one packet per channel again, the address counters read 1
//------------------------------------------------------------------------------
class router_disable_test extends reg_function_test;

  `uvm_component_utils(router_disable_test)

  extern function new(string name, uvm_component parent);
  extern virtual task access_checks();

  // Packets collected by the three channel monitors so far
  extern function int channel_packets();

  // Wait (bounded) until the channel monitors have collected `expected` packets
  extern task wait_channels(int expected);

endclass : router_disable_test

//------------------------------------------------------------------------------
// router_disable_test -- method implementations
//------------------------------------------------------------------------------

function router_disable_test::new(string name, uvm_component parent);
  super.new(name, parent);
endfunction : new

//------------------------------------------------------------------------------
task router_disable_test::access_checks();
  uvm_status_e status;
  int chan_before;
  int dropped_before;

  // 1. router disabled, every counter enabled
  stage("1. en_reg=0xfe (router_en=0, counters on): 3 packets into a deaf router");
  m_regs.en_reg.write(status, 8'hfe);
  chan_before    = channel_packets();
  dropped_before = m_tb.m_router_module.m_reference.m_dropped_disabled;
  m_seq.start(m_yapp_seqr);                     // 3 packets into a deaf router
  wait_channels(chan_before + 3);           // give a wrong router time to deliver them
  if (channel_packets() != chan_before) begin
    `uvm_error("ROUTER_DIS", $sformatf("%0d packet(s) reached a channel while router_en = 0",
                                       channel_packets() - chan_before))
  end else begin
    `uvm_info("ROUTER_DIS", "router_en = 0: no packet reached a channel", UVM_NONE)
  end
  if (m_tb.m_router_module.m_reference.m_dropped_disabled != dropped_before + 3) begin
    `uvm_error("ROUTER_DIS", "the reference model did not report 3 packets dropped (router disabled)")
  end
  check_counter(m_regs.addr0_cnt_reg, 0);     // a disabled router counts nothing ...
  check_counter(m_regs.addr1_cnt_reg, 0);
  check_counter(m_regs.addr2_cnt_reg, 0);
  check_counter(m_regs.addr3_cnt_reg, 0);
  check_counter(m_regs.parity_err_cnt_reg, 0);
  check_counter(m_regs.oversized_pkt_cnt_reg, 0);
  check_counter(m_regs.mem_size_reg, 0);      // ... and stores nothing

  // 2. router enabled again: traffic and counters resume
  stage("2. en_reg=0xff (router_en=1): 3 packets, traffic and counters resume");
  m_regs.en_reg.write(status, 8'hff);
  chan_before = channel_packets();
  m_seq.start(m_yapp_seqr);
  wait_channels(chan_before + 3);
  if (channel_packets() != chan_before + 3) begin
    `uvm_error("ROUTER_DIS", $sformatf("expected 3 packets on the channels after re-enabling, got %0d",
                                       channel_packets() - chan_before))
  end
  check_counter(m_regs.addr0_cnt_reg, 1);
  check_counter(m_regs.addr1_cnt_reg, 1);
  check_counter(m_regs.addr2_cnt_reg, 1);
  check_counter(m_regs.addr3_cnt_reg, 0);
endtask : access_checks

//------------------------------------------------------------------------------
function int router_disable_test::channel_packets();
  return m_tb.m_chan0.m_rx_agent.m_monitor.m_num_pkt_col
       + m_tb.m_chan1.m_rx_agent.m_monitor.m_num_pkt_col
       + m_tb.m_chan2.m_rx_agent.m_monitor.m_num_pkt_col;
endfunction : channel_packets

//------------------------------------------------------------------------------
task router_disable_test::wait_channels(int expected);
  // a packet needs at most 65 cycles plus the receiver's response delay
  repeat (400) begin
    if (channel_packets() >= expected) begin
      return;
    end
    @(posedge m_tb.m_yapp.m_agent.m_monitor.m_vif.clock);
  end
endtask : wait_channels

files.yapp_project/tb/tests/router_filter_test:
//------------------------------------------------------------------------------
// router_filter_test.sv -- router_filter_test (test plan: DROP-01, DROP-03,
//                          PKT-03, CNT-01, CNT-03)
//------------------------------------------------------------------------------

//------------------------------------------------------------------------------
// router_filter_test: the drop rules and the counters around the maxpktsize
// limit.
//   1. ctrl_reg = 10, en_reg = 0xff; yapp_boundary_seq (lengths 9, 10, 11, 63
//      to addresses 0..3) -> only legal, non-oversized packets reach a
//      channel (scoreboard), oversized_pkt_cnt_reg == packets longer than 10,
//      addr3_cnt_reg == packets to address 3, addrN_cnt_reg == packets sent
//      to N (dropped ones included), parity counter 0
//   2. en_reg = 0x01 (counters off); the same sequence again -> the counters
//      do not move, the drop rules still apply
//------------------------------------------------------------------------------
class router_filter_test extends reg_function_test;

  yapp_boundary_seq m_bnd_seq;

  `uvm_component_utils(router_filter_test)

  extern function new(string name, uvm_component parent);
  extern virtual task access_checks();

  // Run the boundary sequence and wait until the scoreboard judged the forwarded packets
  extern task run_boundary();

endclass : router_filter_test

//------------------------------------------------------------------------------
// router_filter_test -- method implementations
//------------------------------------------------------------------------------

function router_filter_test::new(string name, uvm_component parent);
  super.new(name, parent);
endfunction : new

//------------------------------------------------------------------------------
task router_filter_test::access_checks();
  uvm_status_e status;
  int matched_before;

  m_bnd_seq = yapp_boundary_seq::type_id::create("bnd_seq");
  if (!m_bnd_seq.randomize() with { m_maxpktsize == 6'd10; }) begin
    `uvm_error("FILTER", "bnd_seq.randomize() failed")
  end
  stage("ctrl_reg=10: maxpktsize is 10 for the boundary sequence");
  m_regs.ctrl_reg.write(status, 8'd10);       // maxpktsize = 10

  // 1. every counter enabled
  stage("1. en_reg=0xff: lengths 9/10/11/63 to every address, drops counted");
  m_regs.en_reg.write(status, 8'hff);
  matched_before = m_tb.m_router_module.m_scoreboard.m_packets_matched;
  run_boundary();
  if (m_tb.m_router_module.m_scoreboard.m_packets_matched != matched_before + m_bnd_seq.m_sent_forwarded) begin
    `uvm_error("FILTER", $sformatf("scoreboard matched %0d packets, expected %0d",
                                   m_tb.m_router_module.m_scoreboard.m_packets_matched - matched_before, m_bnd_seq.m_sent_forwarded))
  end
  if (m_tb.m_router_module.m_scoreboard.m_packets_unexpected != 0) begin
    `uvm_error("FILTER", "a dropped packet reached a channel")
  end
  check_counter(m_regs.oversized_pkt_cnt_reg, m_bnd_seq.m_sent_oversized);
  check_counter(m_regs.addr3_cnt_reg, m_bnd_seq.m_sent_per_addr[3]);
  check_counter(m_regs.addr0_cnt_reg, m_bnd_seq.m_sent_per_addr[0]);
  check_counter(m_regs.addr1_cnt_reg, m_bnd_seq.m_sent_per_addr[1]);
  check_counter(m_regs.addr2_cnt_reg, m_bnd_seq.m_sent_per_addr[2]);
  check_counter(m_regs.parity_err_cnt_reg, 0);

  // 2. counters disabled: same traffic, same drops, frozen counters
  stage("2. en_reg=0x01: the same traffic, the same drops, the counters do not move");
  m_regs.en_reg.write(status, 8'h01);
  matched_before = m_tb.m_router_module.m_scoreboard.m_packets_matched;
  run_boundary();
  if (m_tb.m_router_module.m_scoreboard.m_packets_matched != matched_before + m_bnd_seq.m_sent_forwarded) begin
    `uvm_error("FILTER", "the drop rules changed when the counters were disabled")
  end
  check_counter(m_regs.oversized_pkt_cnt_reg, m_bnd_seq.m_sent_oversized);
  check_counter(m_regs.addr3_cnt_reg, m_bnd_seq.m_sent_per_addr[3]);
  check_counter(m_regs.addr0_cnt_reg, m_bnd_seq.m_sent_per_addr[0]);
  check_counter(m_regs.addr1_cnt_reg, m_bnd_seq.m_sent_per_addr[1]);
  check_counter(m_regs.addr2_cnt_reg, m_bnd_seq.m_sent_per_addr[2]);

  stage("ctrl_reg back to 0x3f");
  m_regs.ctrl_reg.write(status, 8'h3f);       // back to the reset value
endtask : access_checks

//------------------------------------------------------------------------------
task router_filter_test::run_boundary();
  int judged_before;
  judged_before = m_tb.m_router_module.m_scoreboard.m_packets_matched + m_tb.m_router_module.m_scoreboard.m_packets_mismatched;
  m_bnd_seq.start(m_yapp_seqr);
  repeat (600) begin
    if (m_tb.m_router_module.m_scoreboard.m_packets_matched + m_tb.m_router_module.m_scoreboard.m_packets_mismatched
        >= judged_before + m_bnd_seq.m_sent_forwarded) begin
      break;
    end
    @(posedge m_tb.m_yapp.m_agent.m_monitor.m_vif.clock);
  end
  repeat (4) begin
    @(posedge m_tb.m_yapp.m_agent.m_monitor.m_vif.clock);
  end
endtask : run_boundary

