  super.do_print(printer);
  printer.print_field("channel_id", m_channel_id, $bits(m_channel_id), UVM_DEC);
  printer.print_field("num_pkt_col", m_num_pkt_col, $bits(m_num_pkt_col), UVM_DEC);
endfunction : do_print

