//------------------------------------------------------------------------------
// router_hbus_addr_coverage.sv -- coverage of the router's HBUS address map
// (test plan COV-04)
//
//   hbus monitor ──► router_module_env.hbus_export ──► analysis_export (write)
//
// Every access, read or write, to every register, to every hole between the
// registers, and to the first, a middle and the last byte of yapp_pkt_mem, of
// the unmapped range 0x1050-0x10ff and of yapp_mem (docs/dut/spec.md, the
// register map; scripts/project_map/regmap.yaml). Accesses outside
// 0x1000-0x11ff are not binned.
//------------------------------------------------------------------------------
class router_hbus_addr_coverage extends uvm_subscriber #(hbus_transaction);

  int m_num_sampled;

  covergroup hbus_addr_cg with function sample(bit[15:0] addr, bit write);
    option.per_instance = 1;
    addr_cp : coverpoint addr {
      // the registers
      bins ctrl           = {16'h1000};
      bins en             = {16'h1001};
      bins parity_cnt     = {16'h1004};
      bins m_oversized_cnt  = {16'h1005};
      bins addr3_cnt      = {16'h1006};
      bins addr0_cnt      = {16'h1009};
      bins addr1_cnt      = {16'h100a};
      bins addr2_cnt      = {16'h100b};
      bins m_mem_size       = {16'h100d};
      // the unmapped addresses between them: read 0, writes ignored
      bins reg_hole[]     = {16'h1002, 16'h1003, 16'h1007, 16'h1008, 16'h100c, 16'h100e, 16'h100f};
      // yapp_pkt_mem (read-only), the unmapped range, yapp_mem (read-write)
      bins pkt_mem_first  = {16'h1010};
      bins pkt_mem_mid    = {[16'h1011:16'h104e]};
      bins pkt_mem_last   = {16'h104f};
      bins gap_first      = {16'h1050};
      bins gap_mid        = {[16'h1051:16'h10fe]};
      bins gap_last       = {16'h10ff};
      bins yapp_mem_first = {16'h1100};
      bins yapp_mem_mid   = {[16'h1101:16'h11fe]};
      bins yapp_mem_last  = {16'h11ff};
    }
    rw_cp : coverpoint write {
      bins read  = {0};
      bins write = {1};
    }
    addr_x_rw : cross addr_cp, rw_cp;
  endgroup : hbus_addr_cg

  `uvm_component_utils(router_hbus_addr_coverage)

  extern function new(string name, uvm_component parent);

  // One HBUS access from the monitor
  extern function void write(hbus_transaction t);

  extern function void report_phase(uvm_phase phase);

endclass : router_hbus_addr_coverage

//------------------------------------------------------------------------------
// router_hbus_addr_coverage -- method implementations
//------------------------------------------------------------------------------

function router_hbus_addr_coverage::new(string name, uvm_component parent);
  super.new(name, parent);
  hbus_addr_cg = new();
endfunction : new

//------------------------------------------------------------------------------
function void router_hbus_addr_coverage::write(hbus_transaction t);
  m_num_sampled++;
  hbus_addr_cg.sample(t.m_haddr, t.m_hwr_rd == HBUS_OP_WRITE);
endfunction : write

//------------------------------------------------------------------------------
function void router_hbus_addr_coverage::report_phase(uvm_phase phase);
  `uvm_info(get_type_name(), $sformatf("HBUS address coverage: %0d accesses sampled, coverage %.1f%%",
                                       m_num_sampled, hbus_addr_cg.get_inst_coverage()), UVM_LOW)
endfunction : report_phase

files.yapp_project/uvc/router/router_hbus_bits:
//------------------------------------------------------------------------------
// router_hbus_bits_coverage.sv -- every bit of the read-write registers written
// as 0 and as 1 (test plan COV-05)
//
//   hbus monitor ──► router_module_env.hbus_export ──► analysis_export (write)
//
// One sample per bit of every HBUS write to ctrl_reg (0x1000) or en_reg
// (0x1001): which register, which bit, which value. The reserved bits
// (ctrl_reg[7:6], en_reg[3]) are read-write too, so they count.
//------------------------------------------------------------------------------
class router_hbus_bits_coverage extends uvm_subscriber #(hbus_transaction);

  int m_num_writes;

  covergroup hbus_bits_cg with function sample(bit is_en, int bit_index, bit value);
    option.per_instance = 1;
    reg_cp : coverpoint is_en {
      bins m_ctrl_reg = {0};
      bins m_en_reg   = {1};
    }
    bit_cp : coverpoint bit_index {
      bins b[] = {[0:7]};
    }
    val_cp : coverpoint value {
      bins zero = {0};
      bins one  = {1};
    }
    reg_x_bit_x_val : cross reg_cp, bit_cp, val_cp;
  endgroup : hbus_bits_cg

  `uvm_component_utils(router_hbus_bits_coverage)

  extern function new(string name, uvm_component parent);

  // One HBUS access from the monitor; only writes to ctrl_reg / en_reg count
  extern function void write(hbus_transaction t);

  extern function void report_phase(uvm_phase phase);

endclass : router_hbus_bits_coverage

//------------------------------------------------------------------------------
// router_hbus_bits_coverage -- method implementations
//------------------------------------------------------------------------------

function router_hbus_bits_coverage::new(string name, uvm_component parent);
  super.new(name, parent);
  hbus_bits_cg = new();
endfunction : new

//------------------------------------------------------------------------------
function void router_hbus_bits_coverage::write(hbus_transaction t);
  if (t.m_hwr_rd != HBUS_OP_WRITE || !(t.m_haddr inside {16'h1000, 16'h1001})) begin
    return;
  end
  m_num_writes++;
  for (int i = 0; i < 8; i++) begin
    hbus_bits_cg.sample(t.m_haddr == 16'h1001, i, t.m_hdata[i]);
  end
endfunction : write

//------------------------------------------------------------------------------
function void router_hbus_bits_coverage::report_phase(uvm_phase phase);
  `uvm_info(get_type_name(), $sformatf("HBUS register bits coverage: %0d writes to ctrl_reg/en_reg, coverage %.1f%%",
                                       m_num_writes, hbus_bits_cg.get_inst_coverage()), UVM_LOW)
endfunction : report_phase

files.yapp_project/uvc/router/router_hbus_coun:
//------------------------------------------------------------------------------
// router_hbus_counter_coverage.sv -- the values the counters were read with
// (test plan COV-07)
//
//   hbus monitor ──► router_module_env.hbus_export ──► analysis_export (write)
//
// One sample per HBUS read of a counter register: which of the six counters,
// and whether it read 0, a value in between or 255 (the last value before it
// wraps, docs/dut/spec.md "Decisions").
//------------------------------------------------------------------------------
class router_hbus_counter_coverage extends uvm_subscriber #(hbus_transaction);

  int m_num_sampled;

  covergroup hbus_counter_cg with function sample(int counter, bit[7:0] value);
    option.per_instance = 1;
    counter_cp : coverpoint counter {
      bins parity_err = {0};
      bins oversized  = {1};
      bins addr0      = {2};
      bins addr1      = {3};
      bins addr2      = {4};
      bins addr3      = {5};
    }
    value_cp : coverpoint value {
      bins zero = {8'd0};
      bins mid  = {[8'd1:8'd254]};
      bins max  = {8'd255};
    }
    counter_x_value : cross counter_cp, value_cp;
  endgroup : hbus_counter_cg

  `uvm_component_utils(router_hbus_counter_coverage)

  extern function new(string name, uvm_component parent);

  // One HBUS access from the monitor; only reads of a counter count
  extern function void write(hbus_transaction t);

  extern function void report_phase(uvm_phase phase);

endclass : router_hbus_counter_coverage

//------------------------------------------------------------------------------
// router_hbus_counter_coverage -- method implementations
//------------------------------------------------------------------------------

function router_hbus_counter_coverage::new(string name, uvm_component parent);
  super.new(name, parent);
  hbus_counter_cg = new();
endfunction : new

//------------------------------------------------------------------------------
function void router_hbus_counter_coverage::write(hbus_transaction t);
  int counter;
  if (t.m_hwr_rd != HBUS_OP_READ) begin
    return;
  end
  case (t.m_haddr)
    16'h1004: counter = 0;
    16'h1005: counter = 1;
    16'h1009: counter = 2;
    16'h100a: counter = 3;
    16'h100b: counter = 4;
    16'h1006: counter = 5;
    default:  return;                       // not a counter
  endcase
  m_num_sampled++;
  hbus_counter_cg.sample(counter, t.m_hdata);
endfunction : write

//------------------------------------------------------------------------------
function void router_hbus_counter_coverage::report_phase(uvm_phase phase);
  `uvm_info(get_type_name(), $sformatf("HBUS counter value coverage: %0d counter reads sampled, coverage %.1f%%",
                                       m_num_sampled, hbus_counter_cg.get_inst_coverage()), UVM_LOW)
endfunction : report_phase

files.yapp_project/uvc/router/router_hbus_data:
//------------------------------------------------------------------------------
// router_hbus_data_coverage.sv -- data patterns written to and read from
// yapp_mem (test plan COV-06)
//
//   hbus monitor ──► router_module_env.hbus_export ──► analysis_export (write)
//
// One sample per access to the scratch memory yapp_mem (0x1100-0x11ff): read
// or write, and the byte: all zeros, all ones, 0x55, 0xaa or any other value.
//------------------------------------------------------------------------------
class router_hbus_data_coverage extends uvm_subscriber #(hbus_transaction);

  int m_num_sampled;

  covergroup hbus_data_cg with function sample(bit write, bit[7:0] data);
    option.per_instance = 1;
    rw_cp : coverpoint write {
      bins read  = {0};
      bins write = {1};
    }
    pattern_cp : coverpoint data {
      bins zeros = {8'h00};
      bins ones  = {8'hff};
      bins x55   = {8'h55};
      bins xaa   = {8'haa};
      bins other = {[8'h01:8'h54], [8'h56:8'ha9], [8'hab:8'hfe]};
    }
    rw_x_pattern : cross rw_cp, pattern_cp;
  endgroup : hbus_data_cg

  `uvm_component_utils(router_hbus_data_coverage)

  extern function new(string name, uvm_component parent);

  // One HBUS access from the monitor; only yapp_mem counts
  extern function void write(hbus_transaction t);

  extern function void report_phase(uvm_phase phase);

endclass : router_hbus_data_coverage

//------------------------------------------------------------------------------
// router_hbus_data_coverage -- method implementations
//------------------------------------------------------------------------------

function router_hbus_data_coverage::new(string name, uvm_component parent);
  super.new(name, parent);
  hbus_data_cg = new();
endfunction : new

//------------------------------------------------------------------------------
function void router_hbus_data_coverage::write(hbus_transaction t);
  if (t.m_haddr < 16'h1100 || t.m_haddr > 16'h11ff) begin
    return;
  end
  m_num_sampled++;
  hbus_data_cg.sample(t.m_hwr_rd == HBUS_OP_WRITE, t.m_hdata);
endfunction : write

//------------------------------------------------------------------------------
function void router_hbus_data_coverage::report_phase(uvm_phase phase);
  `uvm_info(get_type_name(), $sformatf("HBUS yapp_mem data coverage: %0d accesses sampled, coverage %.1f%%",
                                       m_num_sampled, hbus_data_cg.get_inst_coverage()), UVM_LOW)
endfunction : report_phase

